"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9243],{28831:e=>{e.exports=JSON.parse('{"functions":[{"name":"seedDefaultItems","desc":"Backfills a player\'s empty inventory with `STUDIO_DEFAULT_ITEMS`. No-ops\\nwhen the inventory is missing or already holds anything, so it can never\\nduplicate a seed.\\n\\nOnly called from [InventoryService.start] under `RunService:IsStudio()`.","params":[{"name":"player","desc":"player to seed","lua_type":"Player"}],"returns":[],"function_type":"static","source":{"line":151,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"start","desc":"Boots the service. For every already-loaded profile, and for every future\\n[ProfileService.ProfileLoaded], it seeds Studio defaults (Studio only), then\\ncompacts bag indexes, compacts hotbar slot indexes, and pulls bag items up\\ninto any empty hotbar slots \u2014 in that order, since each pass depends on the\\nprevious one having closed its gaps.","params":[],"returns":[],"function_type":"static","source":{"line":172,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"getPlayerInventory","desc":"Returns the player\'s live inventory array, or nil when no profile is loaded.\\n\\nThe returned table is the profile\'s own storage, not a copy \u2014 mutating it\\nmutates player data, and any mutation must be followed by\\n`ProfileService.update(player, { \\"inventory\\" })` to replicate.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"Types.Inventory?"}],"function_type":"static","source":{"line":216,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"recordIdExists","desc":"Returns whether a record with the given id is present in the player\'s\\ninventory. Used as a cheap ownership guard before acting on a client-supplied\\nrecordId.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"recordId","desc":"record id to look for","lua_type":"Types.RecordId"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":238,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"removeRecord","desc":"Removes an item record from the player\'s inventory by its recordId.\\nThis is a hard removal and does not consider item quantity.\\nYou should typically use `subtractQuantityFromItemRecord` or `subtractQuantityFromItemId` instead.\\nThis function is mainly used by InventoryService itself.\\n\\nLeaves a hole in the slot/bag index sequence \u2014 run\\n[InventoryService.cleanBagIndexes] or [InventoryService.cleanSlotIndexes]\\nafterwards if the ordering matters.","params":[{"name":"player","desc":"The player whose inventory to modify","lua_type":"Player"},{"name":"recordId","desc":"The unique ID of the item record to remove","lua_type":"Types.RecordId"}],"returns":[{"desc":"Whether the removal was successful","lua_type":"boolean"}],"function_type":"static","source":{"line":274,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"addRecord","desc":"Appends a fully-formed record to the player\'s inventory, rejecting it if a\\nrecord with the same id is already present.\\n\\nLow level: the caller is responsible for having allocated a valid\\n`slotIndex` or `bagIndex` on the record. Prefer\\n[InventoryService.addQuantityToItemId], which does that allocation and the\\nstack math for you.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"record","desc":"record to insert","lua_type":"Types.ItemRecord"}],"returns":[{"desc":"false when the recordId is already present","lua_type":"boolean"}],"function_type":"static","source":{"line":310,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"getRecordsByItemId","desc":"Grabs all items in the player\'s inventory that match the given itemId.\\n\\nSince multiple records can hold the same itemId, this function\\nmust return a table of records instead of a single record.\\n\\nThe returned array is a new table, but the records inside it are the live\\nprofile records \u2014 mutating `record.quantity` mutates player data.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"itemId","desc":"item id to match","lua_type":"string"}],"returns":[{"desc":"nil only when no profile is loaded; empty array when simply unowned","lua_type":"{ Types.ItemRecord }?"}],"function_type":"static","source":{"line":345,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"subtractQuantityFromItemId","desc":"Removes a quantity of an item across however many records hold it,\\ndraining **oldest records first** (records are sorted by `createdAt`\\nascending). Records emptied to zero are deleted outright.\\n\\nPass `recordId` to restrict the drain to a single record.\\n\\n:::warning Partial consumption on failure\\nWhen the player holds less than `quantityToSubtract`, this returns false \u2014\\nbut the records it already drained are **not** restored. Check\\n[InventoryService.getTotalItemQuantity] first if the operation must be\\nall-or-nothing.\\n:::","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"itemId","desc":"item to consume","lua_type":"string"},{"name":"quantityToSubtract","desc":"how much to remove","lua_type":"number"},{"name":"recordId","desc":"restrict consumption to this record only","lua_type":"string?"}],"returns":[{"desc":"false when the full quantity could not be removed","lua_type":"boolean"}],"function_type":"static","source":{"line":381,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"addQuantityToItemId","desc":"Adds a quantity of an item, stacking into existing records and spilling into\\nnew ones as needed.\\n\\nWithout `props`: tops up the first record for that item that is below\\n`InventoryData.MAX_STACK`, then mints additional full-or-partial records\\nuntil the requested quantity is placed. With `props`: skips stacking and\\nalways creates exactly one new record, because prop-bearing records are not\\ninterchangeable with plain ones.\\n\\nEach new record is placed in the first free hotbar slot\\n([InventoryService.getFirstAvailableSlot]); if the hotbar is full it gets a\\n`bagIndex` from [InventoryService.getNextBagIndex] instead. Every new record\\nis dispatched to the client as `ITEM_SHOP_ITEM_ADD`.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"itemId","desc":"item to add","lua_type":"string"},{"name":"quantityToAdd","desc":"how much to add; must be positive","lua_type":"number"},{"name":"props","desc":"per-record props; forces a dedicated record","lua_type":"{ [string]: any }?"}],"returns":[{"desc":"false on bad arguments or a missing profile","lua_type":"boolean"},{"desc":"the records newly created (not the topped-up one)","lua_type":"{ Types.ItemRecord }?"}],"function_type":"static","source":{"line":455,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"getTotalItemQuantity","desc":"Sums the quantity of an item across every record holding it. Returns 0 when\\nno profile is loaded or the item is unowned.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"itemId","desc":"item to total","lua_type":"string"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":584,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"getItemRecord","desc":"Searches for a record by its recordId and returns the live record (not a\\ncopy), or nil when absent.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"recordId","desc":"record id to fetch","lua_type":"Types.RecordId"}],"returns":[{"desc":"","lua_type":"Types.ItemRecord?"}],"function_type":"static","source":{"line":613,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"subtractQuantityFromItemRecord","desc":"Removes a quantity from one specific record. Deletes the record when the\\nquantity exactly reaches zero, and refuses (returns false, changing nothing)\\nwhen the record holds less than requested \u2014 unlike\\n[InventoryService.subtractQuantityFromItemId], this is all-or-nothing.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"recordId","desc":"record to drain","lua_type":"Types.RecordId"},{"name":"quantityToSubtract","desc":"amount to remove, defaults to 1","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":646,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"isSlotTaken","desc":"Returns whether any record currently occupies the given hotbar slot.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"slotIndex","desc":"hotbar slot to test","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":684,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"getFirstAvailableSlot","desc":"Returns the lowest unoccupied hotbar slot in\\n`1 .. InventoryData.MAX_HOTBAR_SLOTS`, or nil when the hotbar is full.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"number?"}],"function_type":"static","source":{"line":710,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"getNextBagIndex","desc":"Allocates the next bag index as `highest existing bagIndex + 1`, or 1 when\\nthe bag is empty or no profile is loaded.\\n\\nThis is a monotonic allocator, not a gap filler: removing a bag item leaves\\nits index permanently unused until\\n[InventoryService.cleanBagIndexes] renumbers the bag. That is what keeps bag\\nindexes unique despite [InventoryService.setItemBagIndex] performing no\\ncollision check of its own.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":744,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"fillEmptyHotbarSlots","desc":"Pulls bag items up into every empty hotbar slot, lowest slot first, taking\\nthe first bag record encountered for each. Run at profile load so a player\\nnever boots with a hole in their hotbar while items sit unused in the bag.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"}],"returns":[],"function_type":"static","source":{"line":773,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"demoteHotbarRecords","desc":"Moves every record that still holds a hotbar `slotIndex` into the bag. Run\\nat profile load while `FeatureFlags.Hotbar` is off so nothing sits in an\\ninvisible hotbar slot.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"}],"returns":[],"function_type":"static","source":{"line":814,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"cleanSlotIndexes","desc":"Renumbers hotbar slots to be sequential from 1, closing any gaps.\\n\\nWorks by sorting the inventory array by `slotIndex` ascending \u2014 bag records\\nsort last because their nil index is treated as `math.huge` \u2014 so the\\nhotbar records land in array positions `1 .. n` and each is then assigned\\nits own array position as its new `slotIndex`. Bag records are skipped and\\nkeep their `bagIndex` untouched.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"}],"returns":[{"desc":"false only when no profile is loaded","lua_type":"boolean"}],"function_type":"static","source":{"line":843,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"cleanBagIndexes","desc":"Cleans up bag indexes to be sequential starting from 1 \u2014 closes any gaps.\\n\\nThe mirror of [InventoryService.cleanSlotIndexes], sorting on `bagIndex`\\ninstead so bag records occupy array positions `1 .. n` and take those\\npositions as their new indexes. Hotbar records sort last and are skipped.\\n\\nThis is the only thing that reclaims the gaps left by\\n[InventoryService.getNextBagIndex]\'s monotonic allocation, so it should run\\nafter any batch of bag removals.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"}],"returns":[{"desc":"false only when no profile is loaded","lua_type":"boolean"}],"function_type":"static","source":{"line":884,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"setItemSlot","desc":"Assigns a record to a hotbar slot, refusing the write when that slot is\\nalready occupied. Passing `slotIndex = nil` clears the record\'s slot and\\nskips the occupancy check.\\n\\nDoes not touch `bagIndex` \u2014 callers moving an item into the hotbar must also\\ncall [InventoryService.unsetItemBagIndex] to preserve the one-index-only\\ninvariant.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"recordId","desc":"record to place","lua_type":"Types.RecordId"},{"name":"slotIndex","desc":"target hotbar slot, or nil to clear","lua_type":"number?"}],"returns":[{"desc":"false when the slot is taken or the record is missing","lua_type":"boolean"}],"function_type":"static","source":{"line":925,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"unsetItemSlot","desc":"Clears a record\'s hotbar slot, freeing it for another item. Shorthand for\\n[InventoryService.setItemSlot] with a nil slot.\\n\\nLeaves the record with neither index set, so the caller is expected to\\nfollow up with [InventoryService.setItemBagIndex].","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"recordId","desc":"record to clear","lua_type":"Types.RecordId"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":973,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"setItemBagIndex","desc":"Assigns a record\'s bag index. Passing nil clears it.\\n\\n:::caution No collision check\\nUnlike [InventoryService.setItemSlot], this performs no uniqueness check \u2014\\ntwo records can end up sharing a bagIndex if a caller supplies a literal\\nvalue. Always source the index from\\n[InventoryService.getNextBagIndex].\\n:::","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"recordId","desc":"record to reindex","lua_type":"Types.RecordId"},{"name":"bagIndex","desc":"new bag index, or nil to clear","lua_type":"number?"}],"returns":[{"desc":"false when the record is missing","lua_type":"boolean"}],"function_type":"static","source":{"line":995,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"unsetItemBagIndex","desc":"Clears a record\'s bag index. Shorthand for\\n[InventoryService.setItemBagIndex] with nil, used after a record has been\\nplaced into a hotbar slot.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"recordId","desc":"record to clear","lua_type":"Types.RecordId"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":1031,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"moveToHotbar","desc":"Moves an item from the bag into a specific hotbar slot. Backs the drag-drop\\nflow from the client.\\n\\nValidates the slot is in range and the record is genuinely owned, then:\\n\\n1. Clears the record\'s current slot, if it already sat in the hotbar.\\n2. If the target slot is occupied, evicts the sitting item to the bag by\\n   clearing its slot and giving it a fresh\\n   [InventoryService.getNextBagIndex].\\n3. Places the moving record into the target slot and clears its `bagIndex`.\\n\\nEvery step is rolled back on failure \u2014 the evicted item is restored to the\\nslot it was pushed out of \u2014 so a partial move never leaves two items sharing\\na slot or an item holding both indexes.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"payload","desc":"recordId and target slotIndex","lua_type":"Actions.InventoryMoveToHotbarPayload"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":1061,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"moveToInventory","desc":"Moves an item out of the hotbar and back into the bag: clears its\\n`slotIndex`, then assigns it the next free\\n[InventoryService.getNextBagIndex] so it lands at the end of the bag.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"payload","desc":"recordId to demote","lua_type":"Actions.HotbarMoveToInventoryPayload"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":1209,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"swapSlots","desc":"Swaps the occupants of two hotbar slots.\\n\\nBoth indexes must be in range and distinct, and the source slot must hold an\\nitem; the destination may be empty, in which case this is a plain move. The\\ndestination item is unslotted first so the source can claim its slot without\\ntripping the [InventoryService.setItemSlot] occupancy check, then it takes\\nthe vacated source slot. If that final placement fails, both records are\\nrestored to their original slots.\\n\\nOnly `slotIndex` is touched \u2014 neither item gains a `bagIndex`.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"payload","desc":"fromSlotIndex and toSlotIndex","lua_type":"Actions.HotbarSwapSlotsPayload"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":1257,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"swapBagSlots","desc":"Swap two bag items by their recordIds. Each item must already have a\\n`bagIndex` (i.e. live in the bag, not the hotbar). The bagIndexes are\\nswapped in place \u2014 no slotIndex is touched, so neither item enters the\\nhotbar as a side effect.\\n\\nRejects the swap when the two ids are equal, when either record is missing,\\nwhen either record currently sits in the hotbar (`slotIndex` set), or when\\neither lacks a `bagIndex`. Because it is a pure exchange of two existing\\nindexes it cannot create a collision and needs no rollback path.","params":[{"name":"player","desc":"inventory owner","lua_type":"Player"},{"name":"payload","desc":"fromRecordId and toRecordId","lua_type":"Actions.InventorySwapBagSlotsPayload"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":1367,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"getSellableItemData","desc":"Resolves the item definition backing a sellable record. Cosmetics are\\ndeliberately not merged into `Items` (see `Cosmetics/init.luau`), so the\\nsell path must fall back the same way the shop equip path does.","params":[{"name":"itemId","desc":"item to resolve","lua_type":"string"}],"returns":[{"desc":"","lua_type":"ItemTypes.BaseItem?"}],"function_type":"static","private":true,"source":{"line":1420,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"getSellUnitPrice","desc":"Resolves the per-unit coin price for quick-selling one record.\\n\\nItems carrying an explicit `resaleValue` (seeds, crops, etc.) keep that\\nflat price unchanged. Items without one but carrying a `rarity`\\n(cosmetics) price from `ShopPricing.QUICK_SELL` for that rarity instead.\\nReturns nil when the item has neither, meaning it cannot be sold.","params":[{"name":"itemData","desc":"resolved item definition","lua_type":"ItemTypes.BaseItem"}],"returns":[{"desc":"","lua_type":"number?"}],"function_type":"static","private":true,"source":{"line":1439,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"getSellBlockReason","desc":"Returns a rejection reason for quick-selling this record, or nil when\\nselling is allowed.\\n\\nBlocks:\\n\\n- **Starter item**: [InventoryUtil.isStarterItem], the base Knife and\\n  Pistol every player is gifted. Refused on every record and at every\\n  quantity: a player who sold them would have no weapon skin to fall\\n  back on.\\n- **Equipped**: `inventory_equipped[itemData.type] == record.itemId`.\\n- **Provenance-locked**: `record.props.noSell == true`. This is a\\n  per-record convention for items that must never enter the coin sink \u2014\\n  earned titles, limited claims, and gamepass grants. Nothing sets this\\n  flag yet; the award paths for those features are expected to set it on\\n  the record\'s `props` when they land.\\n\\nBoth sell paths ([InventoryService.sellItem] and\\n[InventoryService.processSellTransaction]) call this before draining\\nanything, so it is the single gate for these rules.","params":[{"name":"player","desc":"seller","lua_type":"Player"},{"name":"record","desc":"record being sold","lua_type":"Types.ItemRecord"},{"name":"itemData","desc":"resolved item definition","lua_type":"ItemTypes.BaseItem"}],"returns":[{"desc":"rejection reason, or nil when selling is allowed","lua_type":"string?"}],"function_type":"static","private":true,"source":{"line":1481,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"isValidSellLine","desc":"Whether a client-sent sell line is well formed: a string recordId and a\\nwhole-number quantity of at least 1. Zero, negative, fractional, NaN and\\ninfinite quantities are refused; a negative one would otherwise grow the\\nstack through [InventoryService.subtractQuantityFromItemRecord].","params":[{"name":"recordId","desc":"client-sent record id","lua_type":"unknown"},{"name":"quantity","desc":"client-sent quantity","lua_type":"unknown"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","private":true,"source":{"line":1518,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"getBatchSellError","desc":"Validates every line of a bulk sell before anything is drained, so one bad\\nline (malformed, a starter or equipped item, a short stack) refuses the\\nwhole batch instead of selling the lines ahead of it. Quantities are summed\\nper record so repeating a recordId cannot oversell its stack.","params":[{"name":"player","desc":"seller","lua_type":"Player"},{"name":"sellItems","desc":"records and quantities to sell","lua_type":"{ InventoryTypes.SellItemData }"}],"returns":[{"desc":"rejection reason, or nil when every line can sell","lua_type":"string?"}],"function_type":"static","private":true,"source":{"line":1539,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"processSellTransaction","desc":"Sell items from player\'s inventory for coins.\\n\\nWalks the requested items, validating each record exists, is sellable\\n(has a `resaleValue` or a `rarity` priced in `ShopPricing.QUICK_SELL`),\\nis not blocked (see [getSellBlockReason]), and holds enough quantity, then\\ndrains it via [InventoryService.subtractQuantityFromItemRecord] and adds\\nthe per-item price adjusted by the record\'s own props to the total. The\\ntotal passes through `BoostData.modifyValueWithBoosts` and is credited\\nonce, after every line has drained.\\n\\n[getBatchSellError] checks every line before the first drain, so a batch\\ncarrying a blocked or malformed line (a starter item, say) sells nothing.\\n\\n:::warning No rollback\\nA failure partway through returns early with the already-drained records\\ngone and the already-credited coins kept. The compensating re-add is present\\nbut commented out.\\n:::","params":[{"name":"player","desc":"seller","lua_type":"Player"},{"name":"sellItems","desc":"records and quantities to sell","lua_type":"{ InventoryTypes.SellItemData }"}],"returns":[{"desc":"whether the sale completed","lua_type":"boolean"},{"desc":"total coins earned on success, error message on failure","lua_type":"string | number"}],"function_type":"static","private":true,"source":{"line":1612,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"sellItem","desc":"Sells a quantity from a single record and credits the player.\\n\\nIndependent of [InventoryService.processSellTransaction] \u2014 this path applies\\n`BoostData.modifyValueWithBoosts` and then the record\'s own props to the\\nbase resale value, and credits exactly once. Unlike the sell-all path it\\ndoes compensate on failure, re-adding the sold quantity when the coin credit\\nfails.\\n\\nReplies to the client with `ITEM_SELL_SUCCESS` or `ITEM_SELL_ERROR` rather\\nthan returning a status.","params":[{"name":"player","desc":"seller","lua_type":"Player"},{"name":"payload","desc":"recordId and quantity","lua_type":"InventoryTypes.InventorySellItemPayload"}],"returns":[],"function_type":"static","source":{"line":1725,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"sellAllItems","desc":"Sells a batch of records in one transaction via\\n[InventoryService.processSellTransaction], then replies to the client with\\n`ITEM_SELL_SUCCESS` (carrying `soldAll` and the coin total) or\\n`ITEM_SELL_ERROR`.\\n\\nInherits the no-rollback caveat documented on\\n[InventoryService.processSellTransaction]. A batch with any blocked or\\nmalformed line (a starter item, say) is refused whole and sells nothing.","params":[{"name":"player","desc":"seller","lua_type":"Player"},{"name":"payload","desc":"the items to sell","lua_type":"InventoryTypes.InventorySellAllPayload"}],"returns":[],"function_type":"static","source":{"line":1848,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"equipItem","desc":"Equips an owned item into the slot for its type, writing\\n`inventory_equipped[itemData.type] = itemId` through\\n[ProfileService.equipItem].\\n\\nVerifies ownership by scanning the inventory for a record with that itemId,\\nso a client cannot equip something it does not hold. The legacy\\n[ItemProcessor] visual-application call that used to follow this is\\ncommented out; cosmetics are applied by [CosmeticService] instead.","params":[{"name":"player","desc":"item owner","lua_type":"Player"},{"name":"itemId","desc":"item to equip","lua_type":"string"}],"returns":[{"desc":"false when the item is unknown or unowned","lua_type":"boolean"}],"function_type":"static","source":{"line":1898,"path":"src/Server/Features/Shop/InventoryService.luau"}},{"name":"unequipItem","desc":"Clears the equipped item for a type by unsetting\\n`inventory_equipped.<itemType>` on the profile.\\n\\nRejects unknown types (`Items.type[itemType]`) and no-ops when nothing is\\nequipped for that type. The legacy [ItemProcessor] unequip call is commented\\nout here as well.","params":[{"name":"player","desc":"item owner","lua_type":"Player"},{"name":"itemType","desc":"key in `Items.type`","lua_type":"string"}],"returns":[{"desc":"false when the type is unknown or nothing was equipped","lua_type":"boolean"}],"function_type":"static","source":{"line":1947,"path":"src/Server/Features/Shop/InventoryService.luau"}}],"properties":[],"types":[],"name":"InventoryService","desc":"Handles player inventory management, including validating, retrieving,\\nadding, and removing items.\\n\\nThe inventory is a flat array of [ItemRecord] stored at\\n`profile.metadata.data.inventory`. Every mutation goes through\\n[ProfileService.update] with the `\\"inventory\\"` key so the player\'s replica\\nstays in sync \u2014 there is no other replication path.\\n\\n## Slot allocation\\n\\nA record lives in exactly one of two places, and which one is encoded by\\nwhich index field is non-nil:\\n\\n- **Hotbar** \u2014 `slotIndex` set (1 .. `InventoryData.MAX_HOTBAR_SLOTS`),\\n  `bagIndex` nil.\\n- **Bag** \u2014 `bagIndex` set (1 .. n), `slotIndex` nil.\\n\\nCallers must never set both. The move helpers\\n([InventoryService.moveToHotbar], [InventoryService.moveToInventory]) keep\\nthe invariant by unsetting the opposite field after a successful set, and\\nroll back to the prior state when any step of a swap fails.\\n\\n`slotIndex` uniqueness is enforced \u2014 [InventoryService.setItemSlot] refuses\\na slot that [InventoryService.isSlotTaken] reports occupied.\\n`bagIndex` uniqueness is **not** enforced by\\n[InventoryService.setItemBagIndex]; it relies on\\n[InventoryService.getNextBagIndex] always handing out\\n`highest existing + 1`. Because that allocator never reuses freed indexes,\\nthe bag develops gaps, which are closed only by\\n[InventoryService.cleanBagIndexes].\\n\\nBoth compaction passes ([InventoryService.cleanSlotIndexes] and\\n[InventoryService.cleanBagIndexes]) work by sorting the inventory array\\nitself \u2014 records with no index sort last via `math.huge` \u2014 and then\\nrewriting each indexed record\'s index to its array position. The physical\\narray order therefore *is* the compacted order, and the two passes reorder\\nthe same array against different keys.\\n\\n## Stacking\\n\\nQuantity is capped per record at `InventoryData.MAX_STACK`.\\n[InventoryService.addQuantityToItemId] tops up the first non-full record for\\nthat item and then spills the remainder into freshly created records.\\nPassing `props` bypasses stacking entirely and always mints a new record,\\nsince props make records non-interchangeable.\\n\\n:::info Persistence\\n`FeatureFlags.SaveInventory` is **off** by default. [ProfileService] clears\\n`inventory` and `inventory_equipped` both on load and before save, so\\ninventories are session-only: nothing here persists across a rejoin. In\\nStudio, [InventoryService.seedDefaultItems] backfills a fresh profile with\\n`STUDIO_DEFAULT_ITEMS` so the hotbar has something to test against.\\n:::\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","realm":["Server"],"source":{"line":62,"path":"src/Server/Features/Shop/InventoryService.luau"}}')}}]);